/* Dark mode: restore the original dark shades (--dark-xxxxxx vars); light mode keeps the theme colours. */
(function(){var H=["1e293b", "ffffff"];function go(){var c=(window.appsmith&&appsmith.theme)||{};c=c.colors||c;var b=String(c.backgroundColor||'').toLowerCase();if(!b&&document.body){var p=document.createElement('i');p.style.color='var(--appsmith-theme-backgroundColor, rgb(1, 2, 3))';document.body.appendChild(p);b=getComputedStyle(p).color;document.body.removeChild(p);if(b==='rgb(1, 2, 3)')b='';}if(!b)return false;if(!/^(#fff(fff)?|white|rgba?\(255, ?255, ?255(, ?1)?\))$/.test(b))H.forEach(function(x){document.documentElement.style.setProperty('--dark-'+x,'#'+x);});return true;}(function t(n){if(!go()&&n>0)setTimeout(function(){t(n-1);},100);})(100);})();
function pretty(k) {
  return k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g, ' $1').trim();
}

function normalizeData(model) {
  return Array.isArray(model && model.rows) ? model.rows : [];
}

function columnsFor(rows, picked) {
  const fields = (Array.isArray(picked) && picked.length > 0)
    ? picked
    : (rows[0] ? Object.keys(rows[0]) : []);
  return fields.map(f => ({
    headerName: pretty(f),
    flex: 1, minWidth: 120,
    field: f,
    valueFormatter: p => (p.value && typeof p.value === 'object') ? JSON.stringify(p.value) : p.value
  }));
}

let gridApi = null;

function renderGrid(model) {
  const rowData = normalizeData(model);
  const columnDefs = columnsFor(rowData, model && model.columns);
  const gridOptions = {
    columnDefs,
    rowData,
    pagination: true,
    paginationPageSize: 50,
    paginationPageSizeSelector: [25, 50, 100, 200, 500],
    defaultColDef: {
      sortable: true,
      resizable: true,
      filter: true,
      enableRowGroup: true,
      enablePivot: true,
      editable: false,
      minWidth: 120,
      menuTabs: ['generalMenuTab', 'filterMenuTab', 'columnsMenuTab']
    },
    rowGroupPanelShow: 'onlyWhenGrouping',
    animateRows: true,
    popupParent: document.body,
    onGridReady: params => { gridApi = params.api; }
  };
  const gridDiv = document.querySelector('#myGrid');
  if (!gridDiv) return;
  gridDiv.innerHTML = '';
  gridApi = agGrid.createGrid(gridDiv, gridOptions);
}

appsmith.onReady(() => {
  renderGrid(appsmith.model);
  appsmith.onModelChange(renderGrid);
});

